antwort.pruefung:
export LC_ALL=C
set -f
l='/var/log/rechenwerk-auth.log'
k='/srv/rechenwerk/log-spiegel/rechenwerk-auth.log'
[ -f "$l" ] && [ ! -L "$l" ] && [ -f "$k" ] && [ ! -L "$k" ] || exit 1
IFS= read -r -d '' logtext < "$l"
IFS= read -r -d '' kopietext < "$k"
logtext=$'\n'$logtext
fehlt=(); n=0
while IFS= read -r z; do
  [[ -n $z && $logtext != *$'\n'"$z"$'\n'* ]] && { fehlt+=("$z"); n=$((n + 1)); }
done <<< "$kopietext"
[ "$n" -ge 1 ] || exit 1
t=${fehlt[0]%% *}
von=${t:11:5}
t=${fehlt[$((n - 1))]%% *}
bis=${t:11:5}
a=${ANTWORT//[[:space:]]/}
[ "$a" = "$von-$bis" ]
